<?php
require_once __DIR__.'/includes/bootstrap.php';require_auth();if(role()!=='admin'){http_response_code(403);exit('Accès réservé à l’administrateur.');}$page_title='Utilisateurs';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pass=$_POST['password']??'';if(strlen($pass)<8){flash('Le mot de passe doit contenir au moins 8 caractères.','error');redirect('users.php');}try{db()->prepare("INSERT INTO users(name,email,password,role) VALUES(?,?,?,?)")->execute([trim($_POST['name']),trim($_POST['email']),password_hash($pass,PASSWORD_DEFAULT),$_POST['role']]);flash('Utilisateur créé.');}catch(Throwable $e){flash('Adresse e-mail déjà utilisée ou données invalides.','error');}redirect('users.php');}
$rows=db()->query("SELECT id,name,email,role,active,created_at FROM users ORDER BY id")->fetchAll();require 'includes/header.php';?>
<div class="panel"><h2>Créer un compte</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="field"><label>Nom complet</label><input name="name" required></div><div class="field"><label>E-mail</label><input type="email" name="email" required></div><div class="field"><label>Mot de passe (8 caractères minimum)</label><input type="password" name="password" minlength="8" required></div><div class="field"><label>Rôle</label><select name="role"><option value="accueil">Accueil</option><option value="production">Production</option><option value="admin">Administrateur</option></select></div><div><button class="btn">Créer l'utilisateur</button></div></form></div><div class="panel"><h2>Comptes existants</h2><table><thead><tr><th>Nom</th><th>E-mail</th><th>Rôle</th><th>Créé le</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['role'])?></td><td><?=date('d/m/Y',strtotime($r['created_at']))?></td></tr><?php endforeach;?></tbody></table></div><?php require 'includes/footer.php';?>
